<?php
namespace App\Services;
use App\Contracts\ResidentKnowledgeService;use App\Models\KnowledgeChunk;use App\Models\Report;use App\Models\User;use App\Services\Rag\OpenRouterService;use Illuminate\Support\Facades\Log;
class OpenRouterResidentKnowledgeService implements ResidentKnowledgeService {
 public function __construct(private readonly OpenRouterService $openRouter) {}
 public function answer(string $question, ?User $resident=null):array {
  if($small=AssistantConversation::resolve($question))return $small+['type'=>'conversation'];
  if($this->isReportQuestion($question))return $this->reportStatus($resident);
  if($this->isClearlyOutOfScope($question))return $this->fallback('I can only assist with verified Barangay Fatima information and services.','out_of_scope');
  if(!$this->openRouter->configured())return $this->fallback('The verified information service is temporarily unavailable. Please contact the barangay office for confirmation.','unavailable');
  $vector=$this->openRouter->embed($question);$results=$this->retrieve($question,$vector);
  Log::info('RAG retrieval completed.',['question'=>$question,'normalized_question'=>$this->normalize($question),'intent'=>'barangay_knowledge','query_embedding_generated'=>(bool)$vector,'candidate_chunks'=>count($results),'top_sources'=>array_column($results,'source_title'),'scores'=>array_column($results,'final_score'),'threshold'=>config('services.rag.similarity_threshold'),'selected_chunks'=>count(array_filter($results,fn($r)=>$r['passed']))]);
  $matches=array_values(array_filter($results,fn($r)=>$r['passed']));
  if(!$matches)return $this->fallback("I couldn't find verified Barangay Fatima information about that.",'no_context');
  $sources=collect($matches)->map(fn($r)=>['id'=>$r['source_id'],'title'=>$r['source_title']])->unique('id')->values()->all();$context=collect($matches)->map(fn($r)=>"SOURCE: {$r['source_title']}\n{$r['chunk']}")->join("\n\n");
  $answer=$this->openRouter->chat($question,$context);Log::info('RAG LLM request completed.',['called'=>true,'succeeded'=>(bool)$answer,'source_ids'=>array_column($sources,'id')]);
  return $answer?['available'=>true,'answer'=>$answer,'type'=>'rag','sources'=>$sources]:$this->fallback('The AI assistant is temporarily unavailable because the configured provider is rate-limited. Please try again later.','llm_unavailable');
 }
 public function inspectRetrieval(string $question):array {return $this->retrieve($question,$this->openRouter->configured()?$this->openRouter->embed($question):null);}
 private function retrieve(string $question,?array $vector):array {$threshold=config('services.rag.similarity_threshold');return KnowledgeChunk::with('document:id,title,is_approved,is_indexed')->whereHas('document',fn($q)=>$q->where('is_approved',true))->get()->map(function($chunk)use($question,$vector,$threshold){$semantic=$vector&&$chunk->embedding&&$chunk->embedding_model===config('services.openrouter.embedding_model')?$this->cosine($vector,$chunk->embedding):0;$lexical=$this->lexicalScore($question,$chunk->document->title,$chunk->content);$final=max($semantic,$lexical);return ['source_id'=>$chunk->document->id,'source_title'=>$chunk->document->title,'chunk'=>$chunk->content,'semantic_score'=>round($semantic,4),'lexical_score'=>round($lexical,4),'final_score'=>round($final,4),'passed'=>$final >= $threshold];})->sortByDesc('final_score')->take(config('services.rag.top_k'))->values()->all();}
 private function lexicalScore(string $question,string $title,string $content):float {$terms=$this->terms($question);if(!$terms)return 0;$title=$this->normalize($title);$content=$this->normalize($content);$titleHits=collect($terms)->filter(fn($t)=>str_contains($title,$t))->count();$contentHits=collect($terms)->filter(fn($t)=>str_contains($content,$t))->count();return min(1,($titleHits/count($terms))*0.8+($contentHits/count($terms))*0.2);}
 private function terms(string $text):array{return collect(explode(' ',$this->normalize($text)))->filter(fn($t)=>mb_strlen($t)>=3&&!in_array($t,['what','about','tell','with','does','program','barangay','please','explain']))->unique()->values()->all();}
 private function normalize(string $text):string{return trim(preg_replace('/\s+/u',' ',preg_replace('/[^\pL\pN]+/u',' ',mb_strtolower($text))));}
 private function reportStatus(?User $resident):array {if(!$resident)return $this->fallback('Please sign in to check the status of your report.','report_status');$reports=Report::where('resident_id',$resident->id)->latest()->take(3)->get(['reference_number','title','status']);if($reports->isEmpty())return ['available'=>true,'answer'=>'You do not have any submitted reports yet.','type'=>'report_status','sources'=>[]];return ['available'=>true,'answer'=>'Your recent report status: '.$reports->map(fn($r)=>"{$r->reference_number} ({$r->title}): ".str_replace('_',' ',$r->status))->join('; ').'.','type'=>'report_status','sources'=>[]];}
 private function isReportQuestion(string $q):bool{return(bool)preg_match('/\b(my|ako|akong)\b.*\b(report|reklamo|concern)\b|\b(status|update)\b.*\b(report|reklamo)\b/ui',$q);} private function isClearlyOutOfScope(string $q):bool{return(bool)preg_match('/\b(elon musk|celebrity|bitcoin|stock price|weather in|capital of|homework)\b/ui',$q);} private function cosine(array $a,array $b):float {if(count($a)!==count($b)||$a===[])return 0;$dot=$an=$bn=0;foreach($a as $i=>$v){$dot+=$v*$b[$i];$an+=$v**2;$bn+=$b[$i]**2;}return $an&&$bn?$dot/(sqrt($an)*sqrt($bn)):0;} private function fallback(string $answer,string $type):array{return ['available'=>true,'answer'=>$answer,'type'=>$type,'sources'=>[]];}
}
